// @ts-check
import { defineConfig, passthroughImageService } from 'astro/config';
import starlight from '@astrojs/starlight';

// Patterson Academy — the course site for academy.pattersonskills.com.
//
// Every page under curriculum/, lab/, prompts/ and reference.mdx is generated by
// `node scripts/build-course.ts` from the academy-*.js data files at the
// repository root. Those trees are gitignored; CI regenerates them before the
// build. The only hand-written page is src/content/docs/index.mdx.
//
// Branding is applied through src/styles/patterson.css, which remaps Starlight's
// `--sl-*` custom properties onto Patterson brand tokens. No Starlight component
// is ejected, so the theme survives Starlight upgrades.
export default defineConfig({
  site: 'https://academy.pattersonskills.com',

  // Astro's default image service compiles sharp, which carries an open
  // advisory. The passthrough service copies images through untouched.
  image: { service: passthroughImageService() },

  integrations: [
    starlight({
      title: 'Patterson Academy',
      description:
        'Claude Code training for Patterson teams: sessions, context, memory, skills, subagents, hooks, MCP servers and plugins.',
      tagline: 'Claude Code training for Patterson teams',
      logo: {
        light: './src/assets/patterson-logo-navy.svg',
        dark: './src/assets/patterson-logo-white.svg',
        replacesTitle: true,
      },
      favicon: '/favicon.svg',
      customCss: ['./src/styles/patterson.css', './src/styles/academy.css'],
      // Proxima Nova is served by Adobe Fonts kit uth1qfm. Load it from the kit
      // only — Adobe's terms do not permit re-hosting Typekit payloads, so never
      // commit font binaries or @font-face declarations for it.
      head: [
        {
          tag: 'link',
          attrs: { rel: 'stylesheet', href: 'https://use.typekit.net/uth1qfm.css' },
        },
      ],
      social: [
        {
          icon: 'github',
          label: 'Source repository',
          href: 'https://github.com/patterson-agents/patterson-academy',
        },
        {
          icon: 'external',
          label: 'Patterson Companies',
          href: 'https://www.pattersoncompanies.com',
        },
      ],
      tableOfContents: { minHeadingLevel: 2, maxHeadingLevel: 3 },
      pagination: true,
      expressiveCode: {
        frames: { showCopyToClipboardButton: true },
      },
      // The six curriculum modules are stable, so the groups are declared here
      // and their lessons autogenerate from the extractor's output. Level badges
      // all use the `note` variant: it inherits the brand accent, where the other
      // Starlight variants introduce off-palette reds, oranges and purples.
      // Badge text is sentence case [BG25 p.25].
      sidebar: [
        {
          label: 'Curriculum',
          items: [
            {
              label: 'Getting started',
              badge: { text: 'Beginner', variant: 'note' },
              items: [{ autogenerate: { directory: 'curriculum/getting-started' } }],
            },
            {
              label: 'Sessions, context and memory',
              badge: { text: 'Beginner', variant: 'note' },
              items: [{ autogenerate: { directory: 'curriculum/sessions-context-and-memory' } }],
            },
            {
              label: 'The .claude directory',
              badge: { text: 'Intermediate', variant: 'note' },
              items: [{ autogenerate: { directory: 'curriculum/the-claude-directory' } }],
            },
            {
              label: 'Extending Claude Code',
              badge: { text: 'Intermediate', variant: 'note' },
              items: [{ autogenerate: { directory: 'curriculum/extending-claude-code' } }],
            },
            {
              label: 'Plugins and distribution',
              badge: { text: 'Advanced', variant: 'note' },
              items: [{ autogenerate: { directory: 'curriculum/plugins-and-distribution' } }],
            },
            {
              label: 'Advanced topics',
              badge: { text: 'Advanced', variant: 'note' },
              items: [{ autogenerate: { directory: 'curriculum/advanced-topics' } }],
            },
          ],
        },
        {
          label: 'Lab',
          items: [{ autogenerate: { directory: 'lab' } }],
        },
        {
          label: 'Prompt library',
          items: [{ autogenerate: { directory: 'prompts' } }],
        },
        {
          label: 'Reference',
          items: [{ label: 'Documentation index', link: '/reference/' }],
        },
      ],
    }),
  ],
});
